public class Q30_Real_Life_Multithreading_Tasks { static class Task implements Runnable { private final String taskName; Task(String taskName){this.taskName=taskName;} public void run(){for(int i=1;i<=5;i++){System.out.println(taskName+" processing item "+i);try{Thread.sleep(150);}catch(InterruptedException e){Thread.currentThread().interrupt();return;}}} } public static void main(String[] args) throws InterruptedException { Thread download=new Thread(new Task("Download task")); Thread process=new Thread(new Task("Data processing task")); Thread print=new Thread(new Task("Print task")); download.start();process.start();print.start();download.join();process.join();print.join();System.out.println("All tasks completed."); } }
